contracts={'campaign':'G175','firmware_parent_sha256':view['parent_sha256'],'QSR_trace':{'observed_descriptor':'6024b728 has format pointer603d6750 at+8 and caller600b9220 logs the R2 error.','initializer_descriptor':'Pointer603daf60 is at60253a5c; descriptor60253a54 references original code600d8a10. A masked prologue candidate600d8580, seeded only in the analysis ELF, decodes the complete1304-byte initializer including this site.','not_a_general_layout_assumption':'The descriptor+8 path is validated in this exact image; no native call occurs.'},'observed_compiled':{'initializer_600d8580':'chip<11/non-null info; model47 stores table602ab22c in6038ba2c+chip*24h; copies info[6] to6038ba29+chip*24h. Other model cases are20,29,2e,32,4c.','model47_table_602ab22c':{'offset04_enable':'600d6250','offset38_R2_status':'600d6960'},'enable_600d6250':'chip<11; masked write SID from6038ba29+chip*24h,address2646,mask1,caller boolean. Consistent with G170 observed bit clear; no additional invocation.','status_600d6960':'chip<11/non-null output; calls external6009e110 with address2606,length argument9; consumes input bytes0..8 and writes output0..19. Propagates failure without output writes. The lower READ implementation is an explicit model boundary.','field18':'memub+lsr gives unsigned bit7 of2606. Signed-char pseudocode can mislead.','scpq2_initializer_600d8f00':'Model47 uses a separate stride8 array at6038bbb8/table602ab2f8; does not write the SCHG stride24h table.'},'frozen_G174_projection':replay['native_frozen_inputs'],'not_qualified':['Actual live callback-pointer selection/registration is not captured. Native model47 identity and observed2646 behavior are consistent, not a runtime pointer read.','The names/meaning of most fields,including packed field19=44h,are unknown. Nonzero is not proof of fault.','This getter also omits260C/260D; their38h->18h change has no effect on its output. This does not rule out hardware conditions outside this API.','No physical charging or production resource/power/battery owner is established.'],'evidence':{n:load(n)['evidence_id']for n in ['REA-status-log-descriptor.json','REA-QSR-schg-init-model.json','REA-QSR-xrefs-60253a54.json','REA-seeded-InitializePeripheralSchgChgr.json','REA-model47-table.json','REA-model47-R2.json','REA-model47-enable.json','REA-candidate-scpq2-init.json']},'native_bus_reads':0,'new_charger_requests':0}
emit('compiled-contracts.json',contracts)
before=load('entry-native.json')['snapshot'];after=load('final-owner-native.json')['snapshot']
for a in [before,after]:assert a['Running']==1 and a['MapsLive']==2 and a['last_command_id']==2 and a['state']['Phase']==3 and not a['state']['Fault']and not a['state']['Pending']and not a['state']['BatchActive']and a['state']['TxFrames']==11 and a['state']['RxFrames']==22 and not a['state']['PulseAttempted']
